const getCrewMemberEmail = (crewId: string): string => {
  const dynamicUser = users.find(u => u.id === crewId);
  if (dynamicUser && dynamicUser.email) return dynamicUser.email;

  const fallbackMap: Record<string, string> = {
    abbie: 'abbie@7thheaven.com',
    al: 'al@7thheaven.com',
    andrea: 'andrea@7thheaven.com',
    arjun: 'arjun@7thheaven.com',
    chris: 'chris@7thheaven.com',
    daniel: 'daniel@7thheaven.com',
    dave_croke: 'dave.croke@7thheaven.com',
    dave_maas: 'dave.maas@7thheaven.com',
    david_xu: 'david.xu@7thheaven.com',
    emily: 'emily@7thheaven.com',
    emma: 'emma@7thheaven.com',
    erin: 'erin@7thheaven.com',
    francesca: 'francesca@7thheaven.com'
  };
  return fallbackMap[crewId] || `${crewId}@7thheaven.com`;
};

const sendScheduleChangeEmail = async (
  crewId: string,
  actionType: 'added' | 'updated' | 'deleted',
  shiftDetails: { date: string; role: string; startHour: number; endHour: number; venue?: string }
) => {
  if (crewId === 'openshifts') return;

  const emailTo = getCrewMemberEmail(crewId);
  const memberName = findCrewName(crewId);
  const startStr = formatHour(shiftDetails.startHour);
  const endStr = formatHour(shiftDetails.endHour);
  const dateFormatted = new Date(shiftDetails.date + 'T12:00:00').toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric'
  });
  const venueStr = shiftDetails.venue || '7th Heaven Venue';

  let subject = `📅 Schedule Change Alert: Shift ${actionType.toUpperCase()}`;
  let actionDescription = '';
  if (actionType === 'added') {
    actionDescription = `A new shift has been assigned to you:`;
  } else if (actionType === 'updated') {
    actionDescription = `Your shift has been updated:`;
  } else {
    actionDescription = `Your shift has been removed:`;
  }

  const htmlContent = `
    <div style="font-family: sans-serif; background-color: #0c0d12; color: #ffffff; padding: 24px; border-radius: 12px; max-width: 600px; margin: 0 auto; border: 1px solid #1f2937;">
      <h2 style="color: #10b981; margin-top: 0; font-size: 20px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em;">7th Heaven Work Schedule</h2>
      <p style="font-size: 14px; color: #9ca3af; margin-bottom: 20px;">Hello ${memberName},</p>
      <p style="font-size: 14px; color: #e5e7eb; margin-bottom: 20px;">${actionDescription}</p>

      <div style="background-color: #111827; padding: 16px; border-radius: 8px; border: 1px solid #374151; margin-bottom: 20px;">
        <table style="width: 100%; font-size: 14px;">
          <tr>
            <td style="color: #9ca3af; padding: 4px 0; font-weight: bold; width: 80px;">DATE:</td>
            <td style="color: #ffffff; padding: 4px 0;">${dateFormatted}</td>
          </tr>
          <tr>
            <td style="color: #9ca3af; padding: 4px 0; font-weight: bold;">VENUE:</td>
            <td style="color: #ffffff; padding: 4px 0;">${venueStr}</td>
          </tr>
          <tr>
            <td style="color: #9ca3af; padding: 4px 0; font-weight: bold;">ROLE:</td>
            <td style="color: #10b981; padding: 4px 0; font-weight: bold;">${shiftDetails.role}</td>
          </tr>
          <tr>
            <td style="color: #9ca3af; padding: 4px 0; font-weight: bold;">TIME:</td>
            <td style="color: #ffffff; padding: 4px 0;">${startStr} - ${endStr}</td>
          </tr>
        </table>
      </div>

      <p style="font-size: 12px; color: #6b7280; border-top: 1px solid #1f2937; padding-top: 16px; margin-top: 24px;">
        Please log into your <a href="http://localhost:3000/crew" style="color: #10b981; text-decoration: none; font-weight: bold;">Crew Portal</a> to review and accept your shifts.
      </p>
    </div>
  `;

  try {
    await fetch('/api/email', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        to: emailTo,
        subject,
        html: htmlContent
      })
    });
    console.log(`Successfully sent schedule change email to ${emailTo} (${actionType})`);
  } catch (err) {
    console.error('Failed to send schedule email:', err);
  }
};

const addScheduleItem = () => {
  if (!draggedCrewMemberId || !activeDropDay) return;

  if (editingShiftId) {
    const activeAssignments = Object.entries(selectedCrewAssignments).filter(([_, val]) => val.active);
    const firstActiveAssignment = activeAssignments[0];
    const firstActiveCrewId = firstActiveAssignment?.[0] || 'openshifts';
    const firstActiveDetails = firstActiveAssignment?.[1];

    const oldItem = schedules.find(s => s.id === editingShiftId);

    setSchedules(current => {
      let updated = current.map(item => {
        if (item.id === editingShiftId) {
          const sh = firstActiveDetails?.customized ? firstActiveDetails.startHour : dropStartHour;
          const eh = firstActiveDetails?.customized ? firstActiveDetails.endHour : dropEndHour;
          const r = firstActiveDetails?.customized ? firstActiveDetails.role : dropRole;

          if (firstActiveCrewId !== 'openshifts') {
            sendScheduleChangeEmail(firstActiveCrewId, 'updated', {
              date: activeDropDay,
              role: r,
              startHour: sh,
              endHour: eh,
              venue: dropLocation
            });
          }

          if (oldItem && oldItem.crewId !== firstActiveCrewId && oldItem.crewId !== 'openshifts') {
            sendScheduleChangeEmail(oldItem.crewId, 'deleted', {
              date: oldItem.date,
              role: oldItem.role,
              startHour: oldItem.startHour,
              endHour: oldItem.endHour,
              venue: oldItem.location
            });
          }

          return {
            ...item,
            date: activeDropDay,
            crewId: firstActiveCrewId,
            crewName: findCrewName(firstActiveCrewId),
            startHour: sh,
            endHour: eh,
            time: formatTimeFrame(sh, eh),
            role: r.toUpperCase(),
            location: dropLocation,
            notes: dropNotes
          };
        }
        return item;
      });

      if (activeAssignments.length > 1) {
        activeAssignments.slice(1).forEach(([crewId, details], idx) => {
          const newId = 'shift_' + Date.now() + '_' + idx;
          const newItem = {
            id: newId,
            crewId: crewId,
            crewName: findCrewName(crewId),
            date: activeDropDay,
            startHour: details.customized ? details.startHour : dropStartHour,
            endHour: details.customized ? details.endHour : dropEndHour,
            time: formatTimeFrame(details.customized ? details.startHour : dropStartHour, details.customized ? details.endHour : dropEndHour),
            role: (details.customized ? details.role : dropRole).toUpperCase(),
            location: dropLocation,
            notes: dropNotes
          };
          updated.push(newItem);
          sendScheduleChangeEmail(crewId, 'added', {
            date: activeDropDay,
            role: (details.customized ? details.role : dropRole),
            startHour: details.customized ? details.startHour : dropStartHour,
            endHour: details.customized ? details.endHour : dropEndHour,
            venue: dropLocation
          });
        });
      }

      localStorage.setItem('7h_crew_schedules', JSON.stringify(updated));
      window.dispatchEvent(new Event('storage'));

      fetch("/api/crew/calendar", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updated)
      }).catch(err => console.error("Failed to sync schedules:", err));

      return updated;
    });
  } else {
    const activeAssignments = Object.entries(selectedCrewAssignments).filter(([_, val]) => val.active);

    setSchedules(current => {
      let updated = [...current];

      if (activeAssignments.length > 0) {
        activeAssignments.forEach(([crewId, details], idx) => {
          const newId = 'shift_' + Date.now() + '_' + idx;
          const newItem = {
            id: newId,
            crewId: crewId,
            crewName: findCrewName(crewId),
            date: activeDropDay,
            startHour: details.startHour,
            endHour: details.endHour,
            time: formatTimeFrame(details.startHour, details.endHour),
            role: details.role.toUpperCase(),
            location: dropLocation,
            notes: dropNotes
          };
          updated.push(newItem);
          sendScheduleChangeEmail(crewId, 'added', {
            date: activeDropDay,
            role: details.role,
            startHour: details.startHour,
            endHour: details.endHour,
            venue: dropLocation
          });
        });
      } else {
        const newId = 'shift_' + Date.now();
        const newItem = {
          id: newId,
          crewId: draggedCrewMemberId,
          crewName: findCrewName(draggedCrewMemberId),
          date: activeDropDay,
          startHour: dropStartHour,
          endHour: dropEndHour,
          time: formatTimeFrame(dropStartHour, dropEndHour),
          role: dropRole.toUpperCase(),
          location: dropLocation,
          notes: dropNotes
        };
        updated.push(newItem);
        sendScheduleChangeEmail(draggedCrewMemberId, 'added', {
          date: activeDropDay,
          role: dropRole,
          startHour: dropStartHour,
          endHour: dropEndHour,
          venue: dropLocation
        });
      }

      localStorage.setItem('7h_crew_schedules', JSON.stringify(updated));
      window.dispatchEvent(new Event('storage'));

      fetch("/api/crew/calendar", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updated)
      }).catch(err => console.error("Failed to sync schedules:", err));

      return updated;
    });
  }

  saveCustomRole(dropRole);
  setActiveDropDay(null);
  setDraggedCrewMemberId(null);
  setEditingShiftId(null);
};

const deleteScheduleItem = (id: string) => {
  const itemToDelete = schedules.find(item => item.id === id);
  if (itemToDelete && itemToDelete.crewId !== 'openshifts') {
    sendScheduleChangeEmail(itemToDelete.crewId, 'deleted', {
      date: itemToDelete.date,
      role: itemToDelete.role,
      startHour: itemToDelete.startHour,
      endHour: itemToDelete.endHour,
      venue: itemToDelete.location
    });
  }

  setSchedules(current => {
    const updated = current.filter(item => item.id !== id);
    localStorage.setItem('7h_crew_schedules', JSON.stringify(updated));
    window.dispatchEvent(new Event('storage'));

    fetch("/api/crew/calendar", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updated)
    }).catch(err => console.error("Failed to sync schedules:", err));

    return updated;
  });
};

